\item[S2] Yasuaki Gyoda, \emph{An Introduction to the Lagrange and Markov Spectra through the Lens of Generalized Markov Numbers}, arXiv:2609.28097v1 (2026) Chapter 1, Markov equation and Conjecture 1.1.20. \url{https://arxiv.org/pdf/2609.28097}.
